    def initialize
      @locked_fixed = -196608
      @locked_int = 7
      @locked_wide = -12345678901234
      @tail = 0
    end

    def _s_copy_from(other)
      self.locked_fixed = other.locked_fixed
      self.locked_int = other.locked_int
      self.locked_wide = other.locked_wide
      self.tail = other.tail
      self
    end

    def to_h = { locked_fixed: @locked_fixed, locked_int: @locked_int, locked_wide: @locked_wide, tail: @tail }

    def ==(other)
      return false unless other.instance_of?(DegenerateProbe)
      _s_o = other #: DegenerateProbe
      self.locked_fixed == _s_o.locked_fixed && self.locked_int == _s_o.locked_int && self.locked_wide == _s_o.locked_wide && self.tail == _s_o.tail
    end

    def inspect
      "DegenerateProbe(locked_fixed=#{self.locked_fixed.inspect}, locked_int=#{self.locked_int.inspect}, locked_wide=#{self.locked_wide.inspect}, tail=#{self.tail.inspect})"
    end

    def self.read_bits(data, bit_offset: 0)
      stream, rem = ::Ludicrous._s_open_read_stream(data, bit_offset)
      value = DegenerateProbe.new
      raise Refused.new(stream.refusal || "rejected") unless value._s_read(stream)
      [value, stream.bits_processed - rem]
    end

    def self.read(data)
      pair = DegenerateProbe.read_bits(data)
      pair[0]
    end

    def write
      _s_validate("DegenerateProbe")
      stream = WriteStream.new(8)
      begin
        _s_write(stream)
      rescue Serialize::WriteMisuse => _e
        raise InvalidValue.new("DegenerateProbe", _e.message)
      end
      stream.flush
      stream.data
    end

    def _s_read(stream)
      _s_ri = Serialize::Ref.new(0)
      return false unless stream.serialize_fixed(_s_ri, 16, 16, -3, -3)
      self.locked_fixed = _s_ri.value
      self.locked_int = 7
      self.locked_wide = -12345678901234
      return false unless stream.serialize_bits(_s_ri, 8)
      self.tail = _s_ri.value
      true
    end

    def _s_write(stream)
      _s_ri = Serialize::Ref.new(0)
      _s_ri.value = self.locked_fixed
      stream.serialize_fixed(_s_ri, 16, 16, -3, -3)
      _s_ri.value = self.tail
      stream.serialize_bits(_s_ri, 8)
      nil
    end

    def _s_validate(path)
      _s_v1 = self.locked_fixed #: untyped
      unless _s_v1.is_a?(::Integer) && _s_v1 >= -196608 && _s_v1 <= -196608
        ::Ludicrous._s_validate_int(_s_v1, "#{path}.locked_fixed", -196608, -196608)
      end
      _s_v2 = self.locked_int #: untyped
      unless _s_v2.is_a?(::Integer) && _s_v2 >= 7 && _s_v2 <= 7
        ::Ludicrous._s_validate_int(_s_v2, "#{path}.locked_int", 7, 7)
      end
      _s_v3 = self.locked_wide #: untyped
      unless _s_v3.is_a?(::Integer) && _s_v3 >= -12345678901234 && _s_v3 <= -12345678901234
        ::Ludicrous._s_validate_int(_s_v3, "#{path}.locked_wide", -12345678901234, -12345678901234)
      end
      _s_v4 = self.tail #: untyped
      unless _s_v4.is_a?(::Integer) && _s_v4 >= 0 && _s_v4 <= 255
        ::Ludicrous._s_validate_int(_s_v4, "#{path}.tail", 0, 255)
      end
      nil
    end

    def _s_zero
